sysauto_script.script:
// RoleHygiene — scheduled weekly audit
// Copyright (C) 2026 Vladimir Kapustin
// SPDX-License-Identifier: AGPL-3.0
(function scheduledAudit() {
    try {
        var manager = new RoleHygieneManager();
        var summary = manager.runFullAudit({ clear_previous: true });
        gs.info('RoleHygiene audit complete: dormant=' + summary.dormant +
                ', creep=' + summary.creep + ', sod=' + summary.sod +
                ', findings=' + summary.findings_created);
    } catch (e) {
        gs.error('RoleHygiene scheduled audit failed: ' + e);
    }
})();
